/* Intermediate9: delivery permission, retry state and business acknowledgement contracts. */
(function(){
  const N=AG.aws.n,clone=x=>JSON.parse(JSON.stringify(x)),A='123456789012',R='ap-south-1';
  const arn=n=>`arn:aws:sqs:${R}:${A}:${n}`,url=n=>`https://sqs.${R}.amazonaws.com/${A}/${n}`,TOPIC=`arn:aws:sns:${R}:${A}:order-events`;
  const Q=(q,correct,wrong,answer,explain)=>{const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};};
  const table=(heads,rows)=>'<div class="tbl-wrap"><table><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr>'+rows.map(row=>'<tr>'+row.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</table></div><p class="muted">Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p>';
  const EVENT={type:'OrderPlaced',eventId:'evt-101',orderId:'order-101',total:499};
  const policy=n=>({Version:'2012-10-17',Statement:[{Effect:'Allow',Principal:{Service:'sns.amazonaws.com'},Action:'sqs:SendMessage',Resource:arn(n),Condition:{ArnEquals:{'aws:SourceArn':TOPIC}}}]});
  const REDRIVE=JSON.stringify({deadLetterTargetArn:arn('orders-dlq'),maxReceiveCount:'3'});
  const SETTINGS={VisibilityTimeout:'120',ReceiveMessageWaitTimeSeconds:'20',RedrivePolicy:REDRIVE};
  const SUB={RawMessageDelivery:'true',FilterPolicyScope:'MessageBody',FilterPolicy:JSON.stringify({type:['OrderPlaced']})};
  const FILES={
    'queue-attributes.json':{desc:'Standard source: 120 s visibility, 20 s long poll, 3 receives ke baad orders-dlq',content:JSON.stringify(SETTINGS,null,2)},
    'subscription.json':{desc:'Raw OrderPlaced body filter; scope saaf taur par MessageBody',content:JSON.stringify(SUB,null,2)},
    'order.json':{desc:'Pakka business event ID; duplicate deliveries mein bhi wahi ID',content:JSON.stringify(EVENT,null,2)},
    ...Object.fromEntries(['email-queue','invoice-queue'].map(n=>[n+'-policy.json',{desc:'Attribute string map, sabse kam zaroori permission wali SNS SourceArn policy ke saath',content:JSON.stringify({Policy:JSON.stringify(policy(n))},null,2)}]))
  };
  const SOLUTION=[
    `aws sqs create-queue --queue-name orders-dlq --attributes '{"MessageRetentionPeriod":"604800"}'`,
    'aws sqs create-queue --queue-name email-queue --attributes file://queue-attributes.json',
    'aws sqs create-queue --queue-name invoice-queue --attributes file://queue-attributes.json',
    'aws sns create-topic --name order-events',
    `aws sqs set-queue-attributes --queue-url ${url('email-queue')} --attributes file://email-queue-policy.json`,
    `aws sqs set-queue-attributes --queue-url ${url('invoice-queue')} --attributes file://invoice-queue-policy.json`,
    ...['email-queue','invoice-queue'].map(n=>`aws sns subscribe --topic-arn ${TOPIC} --protocol sqs --notification-endpoint ${arn(n)} --attributes file://subscription.json`),
    `aws sns publish --topic-arn ${TOPIC} --message file://order.json`,
    ...['email-queue','invoice-queue'].map(n=>`aws sqs receive-message --queue-url ${url(n)} --max-number-of-messages 1 --wait-time-seconds 20 --message-system-attribute-names All`)
  ];
  const queue=(s,n)=>(s.account.queues||[]).find(q=>q.name===n),topic=s=>(s.account.topics||[]).find(t=>t.arn===TOPIC);
  function scoped(q){const rows=q?.policy?.Statement;return Array.isArray(rows)&&rows.length===1&&rows[0].Effect==='Allow'&&rows[0].Principal?.Service==='sns.amazonaws.com'&&rows[0].Action==='sqs:SendMessage'&&rows[0].Resource===q.arn&&(rows[0].Condition?.ArnEquals?.['aws:SourceArn']===TOPIC||rows[0].Condition?.StringEquals?.['aws:SourceArn']===TOPIC);}
  function configured(s){const qs=s.account.queues||[],dlq=queue(s,'orders-dlq'),t=topic(s);return qs.length===3&&s.account.topics.length===1&&dlq?.attributes?.MessageRetentionPeriod==='604800'&&!dlq.isFifo&&!!t&&t.attributes?.FifoTopic!=='true'&&['email-queue','invoice-queue'].every(n=>{const q=queue(s,n);let r;try{r=JSON.parse(q?.attributes?.RedrivePolicy||'{}');}catch(e){return false;}return !!q&&!q.isFifo&&q.visibilityTimeout===120&&q.attributes.ReceiveMessageWaitTimeSeconds==='20'&&r.deadLetterTargetArn===dlq.arn&&Number(r.maxReceiveCount)===3&&q.attributes.MessageRetentionPeriod==='345600';});}
  const bodyMatches=raw=>{try{const value=JSON.parse(raw);return value&&Object.keys(value).length===Object.keys(EVENT).length&&Object.entries(EVENT).every(([k,v])=>value[k]===v);}catch(e){return false;}};
  function subscriptions(s){const t=topic(s);return !!t&&t.subscriptions.length===2&&['email-queue','invoice-queue'].every(n=>t.subscriptions.some(sub=>sub.protocol==='sqs'&&sub.endpoint===arn(n)&&sub.confirmed&&sub.attributes?.RawMessageDelivery==='true'&&sub.attributes.FilterPolicyScope==='MessageBody'&&(()=>{try{const f=JSON.parse(sub.attributes.FilterPolicy);return Object.keys(f).length===1&&Array.isArray(f.type)&&f.type.length===1&&f.type[0]==='OrderPlaced';}catch(e){return false;}})()));}
  function proof(s,n){const q=queue(s,n),t=topic(s),r=q&&(s.account.messagingReads||[]).find(r=>r.queueId===q.queueId&&r.revision===q.revision);if(!q||!t||!r)return false;return r.messages.some(row=>{const m=q.messages.find(m=>m.messageId===row.MessageId&&m.receiptHandle===row.ReceiptHandle&&m.body===row.Body);return !!m&&m.visibleAt>Date.parse(s.account.now||'2026-10-26T00:00:00Z')+(s.account.messagingClock||0)*1000&&bodyMatches(m.body)&&m.provenance?.topicId===t.topicId&&(s.account.snsDeliveries||[]).some(d=>d.status==='delivered'&&d.publicationId===m.provenance.publicationId&&d.queueId===q.queueId&&d.messageId===m.messageId);});}
  const TASKS=[{text:'Bilkul 2 Standard source queues: 120 s visibility, 20 s polling, 3 receives ke baad 7 din wali DLQ',check:configured},{text:'Har queue sirf SNS order-events ko allow karti hai, exact queue Resource aur SourceArn ke saath',check:s=>['email-queue','invoice-queue'].every(n=>scoped(queue(s,n)))},{text:'Do confirmed raw MessageBody OrderPlaced subscriptions',check:subscriptions},{text:'SNS se aaya asli event email queue mein mila, aaj ki valid receipt ke saath',check:s=>proof(s,'email-queue')},{text:'SNS se aaya asli event invoice queue mein mila, aaj ki valid receipt ke saath',check:s=>proof(s,'invoice-queue')}];
  function plan(k){const poison=k.poison/100,transient=.01,attempts=(1-poison-transient)+transient*Math.min(3,k.retries)+poison*k.retries,capacity=k.workers/(k.seconds+.2)*.8,throughput=capacity/attempts,spare=throughput-k.rate,drain=spare>0?1000/spare:Infinity,overlap=k.visibility<k.seconds+1,window=k.retries*k.visibility,early=k.retries<3?k.rate*3600*transient:0;const ok=k.rate>=20&&k.seconds>=2&&k.poison>=3&&k.workers<=90&&spare>0&&drain<=180&&!overlap&&k.retries>=3&&window<=30;return {attempts,throughput,drain,window,overlap,early,dlq:k.rate*3600*poison,backlog:Math.max(0,1000-spare*3600),ok};}
  const iSeed=()=>({region:R,now:'2026-10-26T00:00:00Z',queues:[{name:'orders-dlq',url:url('orders-dlq'),arn:arn('orders-dlq'),queueId:'original-dlq',isFifo:false,visibilityTimeout:30,attributes:{MessageRetentionPeriod:'604800'},messages:[]},{name:'invoice-queue',url:url('invoice-queue'),arn:arn('invoice-queue'),queueId:'original-invoice',isFifo:false,visibilityTimeout:1,attributes:{VisibilityTimeout:'1'},messages:[{messageId:'original-poison',body:'{"type":"OrderPlaced","eventId":"broken-1","orderId":null}',receiveCount:0},{messageId:'original-good',body:JSON.stringify(EVENT),receiveCount:0}]}],topics:[]});
  const iSolution=[`aws sqs set-queue-attributes --queue-url ${url('invoice-queue')} --attributes file://queue-attributes.json`,...Array(3).fill(`aws sqs receive-message --queue-url ${url('invoice-queue')} --max-number-of-messages 1 --visibility-timeout 0 --message-system-attribute-names All`),`aws sqs receive-message --queue-url ${url('invoice-queue')} --max-number-of-messages 1 --message-system-attribute-names All`,`aws sqs receive-message --queue-url ${url('orders-dlq')} --max-number-of-messages 1 --message-system-attribute-names All`];
  const iTasks=[{text:'Purani source/DLQ bachi; visibility 120 s, redrive 3; achha event sahi-salaamat',check:s=>{const q=queue(s,'invoice-queue'),d=queue(s,'orders-dlq');return s.account.queues.length===2&&q?.queueId==='original-invoice'&&d?.queueId==='original-dlq'&&q.visibilityTimeout===120&&(()=>{try{const r=JSON.parse(q.attributes.RedrivePolicy);return r.deadLetterTargetArn===arn('orders-dlq')&&Number(r.maxReceiveCount)===3;}catch(e){return false;}})()&&q.attributes.ReceiveMessageWaitTimeSeconds==='20'&&q.messages.some(m=>m.messageId==='original-good'&&m.body===JSON.stringify(EVENT));}},{text:'Asli kharab (poison) message 3 source receives ke baad asal mein purani DLQ mein gaya',check:s=>{const q=queue(s,'invoice-queue'),d=queue(s,'orders-dlq'),m=d?.messages.find(m=>m.messageId==='original-poison');return !!q&&!!m&&!q.messages.some(m=>m.messageId==='original-poison')&&m.body===iSeed().queues[1].messages[0].body&&m.deadLetterSourceId==='original-invoice'&&m.receiveCount===4;}},{text:'Asli achha source event dikha; aakhri DLQ receive asli poison body aur aaj ki receipt lautata hai',check:s=>{const q=queue(s,'invoice-queue'),d=queue(s,'orders-dlq'),reads=s.account.messagingReads||[],good=q?.messages.find(m=>m.messageId==='original-good'),poison=d?.messages.find(m=>m.messageId==='original-poison');const time=Date.parse(s.account.now)+(s.account.messagingClock||0)*1000;return !!good&&!!poison&&good.visibleAt>time&&poison.visibleAt>time&&reads.some(r=>r.queueId===q.queueId&&r.revision===q.revision&&r.messages.some(m=>m.MessageId===good.messageId&&m.ReceiptHandle===good.receiptHandle))&&reads.some(r=>r.queueId===d.queueId&&r.revision===d.revision&&r.messages.some(m=>m.MessageId===poison.messageId&&m.ReceiptHandle===poison.receiptHandle&&m.Body===poison.body));}}];
  AG.registerLevels('intermediate',[{
    id:'sqssns',icon:'📨',title:'SQS / SNS: queue, fan-out aur retries',badge:'Message Maestro',
    objectives:['"Accept hua" aur "business ka kaam poora hua" ko alag define karo','Visibility/receipt/DLQ ki state se retry debug karo','Scoped SNS → SQS policy aur body filter banao','FIFO ke order/dedup ko business idempotency se alag rakho'],
    hook:{when:'ShopKaro poore desh mein · team 8 · course ki kahani (fictional)',title:'Email provider dheema hai; checkout kyun ruke?',text:'Priya ka order sahi hai, lekin email provider 5 second leta hai. Ravi SNS → SQS jodta hai. Phir duplicate email aa jaati hai, aur invoice queue mein ek kharab event baar-baar aata hai. Neha kehti hai: order accept hua, invoice ready hua, aur email gayi, teeno ka saboot alag-alag dikhao.'},
    steps:[
      {q:'Sync se async par kab jaayein? Customer ko kya vaada milega?',analogy:'Dhaba counter token deta hai; token ka matlab order accept ho gaya. Token ka matlab yeh nahi ki khana plate mein ready hai. Kitchen ki line aur parosne ka status alag hain.',body:'<p>Checkout ko payment/stock ka zaroori contract tay karna chahiye. Email/PDF ka kaam aam taur par accept hue event ke baad alag se retry ho sakta hai. Zaroori workflows bhi async ho sakte hain, agar pending wala UX, reservation/timeout, milaan aur compensation design kiye hon. Sync/async ka faisla sirf "zaroori/kam zaroori" label se mat karo.</p>',points:['Order commit aur event publish ke beech crash hua toh event kho sakta hai. Usi DB transaction mein outbox record save karo; dispatcher pakke eventId ke saath publish ko retry karta hai. Publish at-least-once ho sakta hai.','Ek SQS queue ke jobs workers mein bat-te hain (competing workers). Email aur invoice services ko apni-apni copy chahiye, isliye SNS ke peeche alag queues. Standard delivery dohra sakti hai aur order badal sakta hai.','Hands-on: dry run mein accept hona, queue delivery, pakka intent aur bahar ki email ka status alag-alag track karo. Success response ko business ka aakhri saboot mat samjho.'],example:'ShopKaro ka target: checkout email ke 5 s ka wait kiye bina order accept bata de; par accept hue order ko phir bhi pakka, nazar mein rakha fulfilment raasta chahiye.',asli:'Pehle API contract, data atomicity aur failure se recovery. Sirf queue jodna end-to-end reliability ka poora design nahi.'},
      {q:'SQS receive karne se message delete kyun nahi hota?',analogy:'Godown ka picker parcel ka token thodi der ke liye apne naam kar leta hai. Picker gir jaaye toh woh reservation khatam ho jaati hai, aur doosra picker kaam le sakta hai. Har reservation par nayi receipt milti hai.',body:'<p>ReceiveMessage → check/process/pakka intent → latest ReceiptHandle se DeleteMessage. Visibility timeout message ko thodi der chhupata hai; kaam poora hua, yeh prove nahi karta. Default 30 second; processing + ack ke liye kaafi margin set karo. Lambe kaam ChangeMessageVisibility se visibility badha sakte hain, pehle receive se 12 ghante tak.</p>',points:['Long polling (WaitTimeSeconds 1..20) khaali receives kam karta hai; zero matlab short polling. HTTP client ka timeout wait time se zyada hona chahiye. Long polling delivery ki der ya message ki retention nahi hai.','Retention default 4 din, 60 second se 14 din tak set ho sakti hai. Queue/message delay (0..900 second) pehli baar dikhne ko taalta hai; visibility receive ke baad lagti hai. Aaj SQS ka max payload 1 MiB; API batch mein 10 messages tak aur kul 1 MiB.','CLI: get-queue-url --queue-name email-queue QueueUrl lautata hai. Send/receive/delete/set attributes --queue-url use karte hain, nakli --queue-name nahi. Receive maange se kam messages de sakta hai. Simulator Standard ka order ya random duplicates nahi banata. Local model purani/expire receipts saaf reject karta hai; asli AWS purani receipt accept karke bhi message delete na kare, aisa ho sakta hai. Local mein queue attributes turant badalte hain; asli mein zyaadatar settings 60 second tak aur retention 15 minute tak le sakti hai.'],code:`aws sqs get-queue-url --queue-name email-queue\naws sqs receive-message --queue-url ${url('email-queue')} --wait-time-seconds 20 --message-system-attribute-names All`,asli:'Aam timing mein visibility ek saath do attempts rokti hai; Standard phir bhi duplicates de sakta hai. Body, receive count, receipt ki umar aur worker ka result saath mein debug karo.'},
      {q:'Kharab (poison) message ko DLQ kab bhejein? Redrive kab safe hai?',analogy:'Na padhe jaane wale pate ka parcel alag jaanch wali shelf par jaata hai. Parcel phenk kar "backlog khatam" bolna repair nahi.',body:'<p>Source queue ki RedrivePolicy mein deadLetterTargetArn aur maxReceiveCount hote hain. Jo message baar-baar receive ho par delete na ho, woh DLQ mein ja sakta hai. DLQ ki RedriveAllowPolicy batati hai kaun se source allowed hain; default allowAll, ya denyAll/byQueue (10 tak source queue ARNs). Is lab mein source aur DLQ same Region/account aur same queue type ke rakho.</p>',points:['Lab ka worker jaan-boojh kar 3 baar retry karta hai. Production mein retry budget naape gaye thodi der ke failures aur backoff se tay hota hai; Lambda SQS ki guidance maxReceiveCount kam se kam 5 kehti hai. Kam maxReceiveCount achhe, thodi der fail hone wale jobs ko bhi jaldi alag kar sakta hai.','DLQ mein jaane ke baad bhi Standard message ki expiry asli enqueue time se hi ginti hai; FIFO mein enqueue timestamp reset hota hai. DLQ ki retention source se lambi rakho. DLQ par ApproximateAgeOfOldestMessage ka apna matlab hai, isliye timestamps aur service metrics dekho.','Alarm lagao: DLQ khaali na ho, sabse purana message, processing errors aur queue ka backlog. Asli fail hui body dekho, producer/consumer theek karo, phir rate limit ke saath canary redrive. FIFO DLQ se nikaalne par business ka zaroori order toot sakta hai; alag rakhna ya haath se order theek karna pad sakta hai.'],code:'{"RedrivePolicy":"{\\"deadLetterTargetArn\\":\\"'+arn('orders-dlq')+'\\",\\"maxReceiveCount\\":\\"3\\"}"}',asli:'Khaali queue safalta ka saboot nahi. Asli jobs bachao; dikhao ki achha kaam aage badh raha hai aur asli poison body alag rakhi gayi hai.'},
      {q:'FIFO ka order aur 5 minute ka dedup kya guarantee karte hain?',analogy:'Bank ki passbook mein entries har account ke hisaab se line mein hain. Har account ek group hai; saare accounts ko ek hi line mein daalna throughput ki rukawat ban sakta hai.',body:'<p>FIFO ke liye .fifo naam aur FifoQueue=true chahiye. MessageGroupId order ka scope tay karta hai. Saaf MessageDeduplicationId, ya sirf body ka content-based SHA-256, producer ke 5 minute ke andar ke duplicate sends rokta hai, message delete hone ke baad bhi. Content-based hash mein attributes nahi gine jaate.</p>',points:['Jis group ka ek message process ho raha hai, us group ke aage ke receives tab tak ruk jaate hain jab tak woh delete ya visibility expire na ho; baaki groups chalte rehte hain. Ek receive batch mein ek group ke kai ordered messages aa sakte hain; consumer ko woh order bachana hai.','Aam (non-high-throughput) FIFO partition har API action par 300 transactions/s support karti hai; 10 ka batch ho toh har partition 3000 messages/s tak. High-throughput mode aur Region quotas limits badalte hain; partitions ka batna, batches, payload aur consumer ki parallelism phir bhi maayne rakhte hain. "Har jagah 300 msg/s" jaisa koi niyam nahi.','Delete se pehle hua business kaam crash ke baad dobara ho sakta hai. FIFO dedup payment/email ko exactly once nahi banata. Aaj Standard mein MessageGroupId fair queues deta hai, FIFO order ke bina, aur fair-queue ka extra request charge lagta hai.'],asli:'Kab use: har account/order/entity ke andar sakht order chahiye. Kab nahi: aapas mein na jude jobs, jinme order ki zaroorat nahi. Pakka eventId aur idempotent business raasta phir bhi zaroori.'},
      {q:'SNS fan-out mein filters, raw body aur FIFO kaise chunein?',analogy:'School ke notice board ka ek hi notice email desk aur print desk dono ko milta hai. Department ka filter tay karta hai ki kaunsa notice kis desk par jaayega; envelope ka format tay karta hai ki desk payload kaise padhega.',body:'<p>SNS topic matching confirmed subscribers ko alag-alag copies bhejta hai. Har consumer queue ki apni retry/retention/DLQ hai. FilterPolicy default se MessageAttributes dekhti hai; body ke JSON fields ke liye FilterPolicyScope=MessageBody chahiye. Policy ki keys AND se judti hain, allowed values OR se. AWS mein filter lagne mein 15 minute tak lag sakte hain; local model turant lagata hai.</p>',points:['RawMessageDelivery=true body seedha bhejta hai; default false message ko SNS ke JSON envelope mein lapet deta hai. Consumer ka contract saaf chuno. Raw SQS subscriptions 10 message attributes tak support karti hain; zyada hon toh client ki taraf delivery errors aate hain.','SNS FIFO SQS FIFO aur Standard dono subscribers support karta hai. Standard subscribers at-least-once/best-effort hi rehte hain. Customer ke seedhe HTTP/email/SMS/mobile subscribers FIFO endpoints nahi; Lambda SQS ke raaste le sakta hai. Eligible SNS FIFO topics mein archive/replay bhi hai; SNS har jagah "na retention, na replay" nahi.','Aaj SNS ka default 256 KiB hai; supported SQS/Lambda/Firehose configs mein MaximumMessageSize se 1 MiB tak badh sakta hai, bade payloads ke liye max 100 subscriptions. Badi files ke liye S3 claim-check theek hai. Body filtering ke scan ka bill lagta hai; attribute filtering free hai.'],code:JSON.stringify(SUB,null,2),asli:'Hands-on: subscription.json raw OrderPlaced JSON body chunta hai. OrderCancelled route nahi hona chahiye. Sirf confirmed subscription se queue tak delivery ki permission nahi milti.'},
      {q:'Publish ka MessageId mila; phir queue khaali kyun?',analogy:'Courier ki booking receipt sirf yeh batati hai ki parcel le liya gaya. Godown ka gate band ho aur courier ke paas andar aane ki permission na ho, toh booking receipt delivery ka saboot nahi.',body:'<p>Producer ki identity ko sns:Publish chahiye. Alag se, destination queue ki resource policy ko exact queue par SNS ka sqs:SendMessage allow karna chahiye, aws:SourceArn se sirf sahi topic tak. Customer-managed KMS key ki extra permissions bhi chahiye ho sakti hain. Cross-account design mein dono taraf review karo.</p>',points:['Topic, subscription ki confirmation/filter/raw settings, queue ki Policy aur delivery metrics/logs padho. Galat account/Region/SourceArn, subscription ki missing permission, KMS denial ya filter mismatch khaali queue ki wajah ho sakti hai.','SNS subscription DLQ delivery ki failures pakadti hai; source SQS ki processing DLQ consumer ke retries khatam hone par. Policy denial jaisi pakki client errors ko theek karna padta hai; yeh mat maano ki har failure delivery tak retry hoti rahegi.','Galti jo sab karte hain: Principal:* policy, filter scope ko attributes par chhod dena, pakka kaam hone se pehle ack karna, alarm hataane ke liye queue delete karna. Production mein aisa hota hai: policy/KMS mein chupchaap badlav ya retention khatam hone se der wala kaam kho jaata hai, jab tak delivery/age alarms aur milaan na ho.'],code:JSON.stringify(policy('email-queue'),null,2),asli:'Main mission ko sabse kam permission wali policy aur dono queues se SNS ki asli body chahiye. Seedha SQS mein daala message ya safal publish ki history se jeet nahi milegi.'},
      {q:'Lambda SQS batch mein ek record fail ho toh kya karein?',analogy:'Das parcels ke batch mein ek ka pata galat hai. Nau safal parcels dobara bhejna bekaar mehnat hai; fail hue parcel ki ID alag se batao.',body:'<p>Event source mapping SQS ko poll karti hai; Lambda ke async invocation destinations source queue ki processing DLQ ki jagah nahi lete. Execution role ko queue ki permissions aur zaroorat ho toh KMS decrypt chahiye. Visibility kam se kam function timeout jitni ho; AWS retry/throttle ki jagah ke liye 6 × function timeout + batching window kehta hai.</p>',points:['ReportBatchItemFailures partial batch responses on karta hai, aur handler ko fail hue message IDs ke saath batchItemFailures lautana padta hai. Sirf flag on karne se, bina sahi handler output ke, fail records alag nahi hote.','FIFO mein pehli failure par processing roko aur fail + bache hue IDs lautao, taaki order bacha rahe. App ke kaam ko phir bhi har event par idempotency/atomicity chahiye.','Example: timeout 10 s + window 5 s = recommended visibility 65 s; visibility 10 s basic validation paas kar leti hai par retry ki recommended jagah nahi deti. Batch size/concurrency aage ki asli limits, queue ki umar, errors aur bheed dekh kar tune karo.'],code:'{"batchItemFailures":[{"itemIdentifier":"failed-message-id"}]}',asli:'Function ka transport safal hona har item ke safal hone ka saboot nahi. Asli failed IDs, pakke kaam aur queue ki umar par nazar rakho; pichhle Lambda lab ka runtime alag saboot hai.'},
      {q:'SQS, SNS, EventBridge, Kinesis ya MQ: kharche ke saath faisla kaise karein?',analogy:'Job ke tokens, notice ki copies, routing desk, dobara padhne wali diary aur purana telephone exchange: sab alag contracts solve karte hain. Service ke naam se pehle kaam ka contract chuno.',body:table(['Need','Candidate','Boundary'],[['Competing workers + buffer','SQS Standard; har entity mein order chahiye toh FIFO','Receipt/delete + idempotent processing; padhe/delete hue jobs event log nahi hain'],['Independent durable copies','SNS → har consumer ki ek SQS','Queue policy/filter, retry/retention, subscription DLQ'],['AWS/SaaS/content ke hisaab se routing + workflow integration','EventBridge','SNS bhi body filter karta hai; sirf filtering nahi, sources/rules/integrations compare karo'],['Order mein rakhe records + har consumer ka alag offset/replay','Kinesis Data Streams','Har shard ka order, partition ka jhukaav, retention aur consumer ka kharcha'],['Pehle se chalte JMS/AMQP broker clients','Amazon MQ','Engine ke apne protocols/HA; broker ki capacity aur maintenance rehti hai']]),points:['Lagbhag us-east-1 ke kul list daam: Standard SQS $0.40/million requests; FIFO $0.50/million eligible message actions; Standard fair queues mein $0.10/million affected requests extra. Standard SNS $0.50/million paid API requests. Har 64 KiB payload ka hissa ek request unit hai; batches, khaali polls aur retries ginti badalte hain.','Example: 3 crore chhote publishes/mahina, 2 queues, har event par har queue mein ek send + receive + delete: SNS lagbhag $15 + SQS lagbhag $72 = $87 ≈ ₹7656 (₹88/$1 par), free allowance/credits se pehle. Yeh sirf requests ka example hai, poora bill nahi: body-filter scans, transfer, KMS, workers, retries, khaali polls, tax aur bade payloads isme nahi.','SNS → SQS par har message ki SNS delivery fees nahi, par SNS data transfer ka charge phir bhi lag sakta hai. Free allowance aur "lab poori free" ko alag samjho. Production ko outbox ki retention/dispatch par nazar aur bahar ke provider se milaan chahiye, sirf broker ki health nahi.'],asli:'Faisla: ek job → SQS; alag copies → SNS + SQS; zyada event integrations → EventBridge; rakhi hui streaming replay → Kinesis; purana broker API → MQ. Failure ka behaviour aur poora kharcha naapo.'}
    ],
    myth:[{myth:'FIFO matlab email/payment sirf ek hi baar ho sakta hai',sach:'Producer ki dedup window aur har group ka order bahar ke kaam ko ek jhatke mein saath nahi jodte. Pakke IDs, durable intents aur provider ke saath milaan/idempotency phir bhi zaroori.'},{myth:'Publish ka MessageId prove karta hai ki har consumer ko event mil gaya',sach:'SNS ka accept karna, subscription ka filter, queue policy/KMS ki delivery aur consumer ka business acknowledgement: chaaron alag states hain.'},{myth:'Ek SQS queue har event email aur invoice dono workers ko de deti hai',sach:'Ek queue mein workers jobs ke liye aapas mein bhidte hain. Alag services ko alag pakki copies chahiye, aam taur par SNS → alag SQS queues.'},{myth:'Queue depth zero hai, matlab retries theek ho gaye',sach:'Purge/delete/expiry kaam mita sakte hain. Source jobs bachao, asli business ke result check karo, aur asli poison body/DLQ dekho.'}],
    playbook:{title:'Kab queue, kab fan-out, kab event log?',use:['Background kaam aur load ko sambhalne ke liye SQS; har alag consumer service ki ek queue','Chune hue entity group mein sakht order ke liye FIFO; har dohraaye business event ke liye idempotency'],avoid:['Broker ne message accept kiya, toh payment/email poora bol dena','Ek global FIFO group, ya bina naape bina limit ke retries','Debugging ke ilaaj mein purge/delete, ya public wildcard queue policy'],how:['Accepted/completed states aur DB + event ki atomicity tay karo','Workers ka share karna vs alag copies vs rakha hua replay chuno','SourceArn policy, filter scope/raw contract, visibility, retention, processing/subscription DLQs set karo','Asli body/receipt, pakka intent, retry ki ginti aur sabse purani umar dekho; canary se recovery'],redflags:['Same eventId, alag payload','Worker ka CPU kam par umar badh rahi; KMS/policy/poison errors','FIFO groups ek hot key mein simat gaye; achhe messages jaldi redrive ho gaye'],rule:'Service ka chunav delivery/order/replay ke contract se hota hai. Business ke shuru se aakhir tak poora hone ka apna saboot chahiye.'},
    exam:[{cue:'Producers ko alag karo aur bhidne wale workers ko scale karo',pick:'SQS',why:'Queue kaam ko thaame rakhti hai; padhne/delete aur retry ka behaviour maayne rakhta hai.'},{cue:'Ek hi event kai alag services ko',pick:'SNS → alag SQS queues',why:'Har consumer ki pakki copy, scoped queue policies ke saath.'},{cue:'Har customer/account mein order',pick:'FIFO + MessageGroupId',why:'Har group ka order; 5 minute ka dedup bahar ke kaam ko atomic nahi banata.'},{cue:'Poison keeps reappearing',pick:'Source RedrivePolicy + processing DLQ',why:'Receive ka budget failures alag karta hai; redrive se pehle dekho aur theek karo.'},{cue:'Publish safal, queue khaali',pick:'Subscription/filter, SQS Policy aur KMS check karo',why:'Accept hona delivery se alag hai; expected SourceArn maayne rakhta hai.'},{cue:'Khaali ReceiveMessage calls kam karo',pick:'20 second tak long polling',why:'Khaali polls kam karta hai; queue delay wali delivery latency nahi.'},{cue:'Pehli processing 10 minute taalo',pick:'DelaySeconds600',why:'Shuru ka delay receive ke baad ki visibility se alag hai; max 15 minute.'},{cue:'Messaging se badi files',pick:'S3 claim-check, ya eligible set kiya bada message',why:'Aaj SQS 1 MiB; SNS default 256 KiB, kuch shartein ke saath 1 MiB tak set ho sakta hai.'},{cue:'Lambda batch ka aadha fail hona',pick:'ReportBatchItemFailures + failed IDs',why:'Handler ka contract aur FIFO order ke niyam phir bhi lagte hain.'}],
    stages:[
      {type:'dryrun',title:'🔬 Accept hua → pahuncha → pakka kaam',goal:'Har click par broker ki state aur business ki state dekho; teen faisle chuno.',nodes:[N('app',100,250,{label:'Order API'}),N('sns',400,250,{label:'Topic'}),N('sqs#mail',650,110,{label:'Email'}),N('sqs#invoice',650,390,{label:'Invoice'}),N('lambda',900,110,{label:'Worker'}),N('sqs#dead',900,390,{label:'DLQ'})],edges:[{from:'app',to:'sns'},{from:'sns',to:'sqs#mail'},{from:'sns',to:'sqs#invoice'},{from:'sqs#mail',to:'lambda'},{from:'sqs#invoice',to:'sqs#dead'}],panels:[{id:'broker',title:'Broker delivery'},{id:'business',title:'Business outcome'}],steps:[
        {say:'Order ka DB commit aur outbox intent pakke hain. Dispatcher pakka eventId evt-101 publish karta hai.',clock:'t=0 s',flows:[{from:'app',to:'sns',label:'event'}],panels:{broker:['SNS accepted publication','Queue tak delivery abhi prove nahi hui'],business:['Order accepted','Email not sent']}},
        {say:'Invoice queue ki policy mein SourceArn ka Allow nahi hai. SNS ne publish accept kiya, par invoice tak delivery deny ho gayi.',flows:[{from:'sns',to:'sqs#invoice',label:'denied',tone:'bad'}],ask:Q('Publish ka MessageId hote hue bhi queue khaali hai: agla debugging kadam?', 'Subscription/filter, destination queue ki policy aur zaroori KMS permissions dekho',['Queue delivery ki permission dekhne se pehle email worker ka timeout badha do','Invoice queue delete kar do aur gayab messages ko poora hua invoice kaam maano','Har producer ko FIFO par le jao aur maan lo ki policy failures safal deliveries ban jaayengi'],0,'Accept hona delivery nahi hai. Permission/filter/KMS dekho; worker timeout SendMessage ki permission nahi deta, delete karne se kaam kho jaata hai, aur FIFO permission ko bypass nahi karta.')},
        {say:'Ravi exact SNS SourceArn ki permission theek karta hai. Dispatcher pakka outbox event dobara publish karta hai; raw OrderPlaced dono queues tak pahunchta hai.',flows:[{from:'sns',to:'sqs#mail',label:'copy',tone:'ok'},{from:'sns',to:'sqs#invoice',label:'copy',tone:'ok'}],panels:{broker:['Do alag queue copies','Matching body filter; scoped permission'],business:['Bahar ki email abhi nahi gayi']}},
        {say:'Email worker email bhejta hai, phir DeleteMessage se pehle crash ho jaata hai. 120 second ki visibility khatam hoti hai; event dobara receive ho sakta hai.',clock:'t=120 s',flows:[{from:'sqs#mail',to:'lambda',label:'try',tone:'slow'}],ask:Q('Email ka result pakka nahi tha, aur wahi eventId dobara aaya. Safe design kya hai?', 'Pakka intent aur provider ki idempotency/milaan use karo; sirf tay kiye pakke contract par ack karo',['Bharosa karo ki FIFO ka 5 minute ka dedup email provider ke har bahar ke kaam ko atomic bana deta hai','Dohraaya event turant delete kar do, pichhla pakka ya bahar ka result dekhe bina','Pehle dedup flag likho, phir baad mein bhejo, bina dispatcher ya pending kaam ki recovery ke'],1,'Pakka intent + idempotent/milaan wala dispatch bahar ki boundary sambhalta hai. FIFO email ko atomic nahi banata; bina dekhe delete se kaam kho sakta hai; akela pehle wala flag crash ke baad email chhod sakta hai.')},
        {say:'Invoice consumer kharab event (orderId=null) ko check nahi kar paata. Teen receives bina delete fail hote hain; agli koshish asli body ko DLQ mein alag kar deti hai.',flows:[{from:'sqs#invoice',to:'sqs#dead',label:'DLQ',tone:'bad'}],panels:{broker:['Source ka retry budget khatam','Poison body DLQ mein bachi'],business:['Achhe jobs aage badh sakte hain','Poison invoice abhi bhi nahi sulajha']},ask:Q('DLQ mein asli kharab event hai. Recovery ka order kya ho?', 'Wajah dekho aur theek karo, limit wali rate par canary redrive karo, business ka asar check karo',['Pehle dono queues purge karo, taaki koi asli fail payload dekhe usse pehle alarms hat jaayein','Bina limit receive retries lagao aur maan lo ki kaafi deliveries ke baad kharab fields sahi ho jaayenge','Achhe jobs bhi delete kar do, taaki saare consumers mein queue metrics ek jaise dikhein'],2,'Asli payload/wajah dekho, theek karo aur control ke saath replay karo. Purge se saboot/kaam kho jaata hai; retries pakki kharabi theek nahi karte; achhe jobs hataane se failure chhupti hai.')},
        {say:'Lab har consumer#eventId ka ek pending-dispatch intent rakhti hai. Duplicate input pehle se bane matching intent ko check karta hai; bahar ki email ka daava nahi.',panels:{broker:['Receipts sirf pakka intent banne ke baad ack hoti hain','SNS delivery DLQ source processing DLQ se alag hai'],business:['Email intent 1; invoice intent 1','Is local lab mein bahar ke sends 0']}}
      ],lesson:'Accept hua event, queue copy, consumer ka pakka intent aur bahar ka kaam: char alag saboot hain.'},
      {type:'flowlab',title:'🎛️ Retry budget aur worker capacity',goal:'Kam se kam 20 msg/s, 2 s ka kaam aur 3% poison rakho. Zyada se zyada 90 worker slots use karo. Shuru ke 1000 jobs 180 s mein khatam karo. Model mein visibility ke overlap se bacho; thodi der ki failures ke liye 3 attempts do. Poison ka visibility-window budget 30 s mein fit ho. Try karo: 20 msg/s, 80 slots, 2 s kaam, visibility 5 s, retries 3, poison 3%.',scenario:'Course ka model, AWS benchmark nahi: 80% utilization ki jagah; processing + 0.2 s acknowledgement; extra 0.8 s timing margin. 1% jobs pehle 2 attempts fail hote hain; chune gaye poison% hamesha fail. Har asli job ke expected attempts mein limit wale retries gine gaye. Poison window = maxReceiveCount × visibility, ek andaazan budget hai, DLQ ki pakki latency nahi. Steady-state DLQ/ghanta mein warmup, sampling aur Standard ke random duplicates nahi gine.',knobs:[{id:'rate',label:'Producer',min:10,max:30,step:10,value:20,unit:'msg/s'},{id:'workers',label:'Concurrent worker slots',min:10,max:100,step:10,value:20,unit:'slots'},{id:'seconds',label:'Processing per attempt',min:1,max:3,step:1,value:2,unit:'s'},{id:'visibility',label:'Visibility timeout',min:1,max:10,step:1,value:1,unit:'s'},{id:'retries',label:'maxReceiveCount',min:1,max:5,step:1,value:1,unit:'receives'},{id:'poison',label:'Permanent poison fraction',min:0,max:6,step:3,value:3,unit:'%'}].map(knob=>({...knob,fmt:v=>v+(knob.unit==='%'?'':' ')+knob.unit})),model:k=>{const p=plan(k);return {readouts:[{label:'Original-job capacity',value:p.throughput.toFixed(1)+' msg/s',tone:p.throughput>k.rate?'ok':'bad'},{label:'Expected attempts / asli job',value:p.attempts.toFixed(2)},{label:'Shuru ke 1000 jobs khatam hone ka time',value:Number.isFinite(p.drain)?Math.ceil(p.drain)+' s':'growing backlog',tone:p.drain<=180?'ok':'bad'},{label:'Backlog after1 hour',value:Math.round(p.backlog)+' jobs'},{label:'Model mein visibility overlap ka khatra',value:p.overlap?'Haan: timeout kaam + margin se kam':'No modeled overlap',tone:p.overlap?'bad':'ok'},{label:'Steady poison DLQ / ghanta',value:Math.round(p.dlq)+' jobs'},{label:'Achhe thodi der wale jobs jaldi alag hue / ghanta',value:Math.round(p.early)+' jobs',tone:p.early?'bad':'ok'},{label:'Poison visibility-window budget',value:p.window+' s',tone:p.window<=30?'ok':'bad'}],verdict:{ok:p.ok,text:p.ok?'Fixed workload bacha, worker budget limit mein, backlog stable aur retry window fit. Asli timing/duplicates abhi bhi naapne hain.':'Capacity, workload, worker budget, visibility margin aur retry window, sab fit hone chahiye; test ki demand kam karna ya jobs delete karna repair nahi.'}};},check:k=>plan(k).ok,lesson:'Zyada retry ki jagah thodi der ki failures se recovery behtar karti hai, par attempts khaati hai aur poison ko alag hone mein der karti hai. FIFO/visibility zero business duplicates ka vaada nahi kar sakte.'},
      {type:'bins',title:'🗂️ Kaam ke contract se service chuno',instructions:'Har saaf zaroorat ke liye ek sabse sahi option; service ka naam nahi, delivery ka contract compare karo.',bins:[{id:'sqs',label:'SQS'},{id:'sns',label:'SNS + SQS'},{id:'events',label:'EventBridge'},{id:'stream',label:'Kinesis'},{id:'mq',label:'Amazon MQ'}],items:[{text:'Aapas mein na jude image jobs, workers mein bate hue',bin:'sqs',explain:'Bhidne wale workers ek queue padhte hain; idempotent processing retries sambhalti hai.'},{text:'Order event ko email aur invoice ki alag pakki copies chahiye',bin:'sns',explain:'Har consumer service ki ek subscribed queue, scoped policies ke saath.'},{text:'AWS/SaaS events + zyada rule integrations',bin:'events',explain:'Event bus ke integrations/rules; SNS bhi body filter karta hai.'},{text:'Rakhe hue ordered records; alag consumers offsets se replay karein',bin:'stream',explain:'Kinesis ka rakha hua stream, partition/shard ke niyam ke saath.'},{text:'Pehle se chalte ActiveMQ JMS clients compatible protocol ke saath migrate',bin:'mq',explain:'Amazon MQ broker clients ke saath compatible hai; supported engine chuno.'}]},
      {type:'order',title:'🔢 Fan-out setup: permission bhi ek step hai',instructions:'Is lab ka order: destination → retry contract → topic → permission → subscription → publish → saboot.',steps:['Source queues aur same type ki DLQ banao','Source ki visibility/retention/redrive policy set karo','SNS topic banao','Har queue par SNS ko SendMessage do, topic SourceArn tak scoped','Har queue ko saaf raw/filter scope ke saath subscribe karo','Pakka OrderPlaced event publish karo','Asli bodies receive karo aur consumer ke results dekho'].map((text,i)=>({text,explain:['Queue ARNs use karne se pehle destinations banao.','Retry ka contract source ka hai; DLQ khatam hue jobs bachati hai.','Topic ARN allowed publisher service ki pehchaan hai.','Queue ki resource policy destination tak delivery ki permission deti hai.','Consumer ka contract raw format aur sahi filter scope chunta hai.','Pakka event ID replay/idempotency mein madad karta hai.','Queue ki asli bodies dekho; broker ka accept karna alag hai.'][i]})),explain:'Scoped policy/subscription se pehle Queue/Topic ARNs bane hone chahiye; sirf Publish ka accept hona shuru se aakhir tak ka saboot nahi.'},
      {type:'triage',title:'🩺 Publish accept hua; invoice queue khaali',symptom:'Course fixture: OrderPlaced Publish ne MessageId lautaya. Email pahunchi; invoice queue mein matching body nahi. AWS ka live capture nahi.',goal:'Delivery ke saare clues chalao; missing destination permission aur sahi fix pehchano.',commands:[{cmd:`aws sns get-topic-attributes --topic-arn ${TOPIC}`,out:'TopicArn: '+TOPIC+'\nSubscriptionsConfirmed: 2',clue:false,note:'Topic hai; confirmation queue ki permission nahi deti.'},{cmd:`aws sns list-subscriptions-by-topic --topic-arn ${TOPIC}`,out:'invoice-queue: confirmed SQS; raw=true; FilterPolicyScope=MessageBody; type=OrderPlaced',clue:false,note:'Subscription aur body filter is event se match karte hain.'},{cmd:`aws sqs get-queue-attributes --queue-url ${url('invoice-queue')} --attribute-names All`,out:'QueueArn: '+arn('invoice-queue')+'\nVisibilityTimeout: 120\nPolicy: absent',clue:true,note:'SNS ke liye queue ki resource policy mein Allow nahi; Publish ne delivery prove nahi ki.'}],questions:[Q('Is khaas delivery failure ki wajah kya hai?', 'Expected SNS topic ke liye destination SQS resource policy mein Allow nahi hai',['Visibility 120 second matlab har naya, na padha message 120 second chhupa rehta hai','Confirmed subscription ka matlab consumer ne invoice safal bhej diya','20 second ka long polling matching events ko pehle worker ke dekhne se pehle delete kar deta hai'],0,'SNS ki SendMessage permission na hona is fixture ko samjhata hai. Visibility receive ke baad shuru hoti hai, confirmation business ka poora hona nahi, aur long polling kaam ka wait karta hai, delete nahi.'),Q('Kaunsa repair sabse kam permission aur debugging ka saboot bachata hai?', 'Is queue par exact topic SourceArn ke liye SNS SendMessage allow karo; delivery phir check karo',['Har principal ko har queue par har SQS action do, taaki aage policy failures na aayein','Email aur invoice queues purge karo, taaki dono ki message ginti ka farak mit jaaye','Delivery se pehle maxReceiveCount ghatao, taaki SNS missing permission ko safal kaam maan le'],1,'Service/action/resource/SourceArn ka scope rakho aur pakka event dobara publish/milaan karo. Public wildcard zaroorat se zyada hai; purge jobs kho deta hai; receive count SQS delivery ke baad consumer ke retries ka hai.')]},
      {type:'terminal',title:'🖥️ Safe OrderPlaced fan-out banao',instructions:'Files taiyaar hain; ls/cat se exact attribute maps, policies aur JSON event dekho. Asli QueueUrl/ARN aur naam wali files use karo. Koi asli AWS call nahi hoti.',goal:'<p><b>1.</b> orders-dlq banao, 7 din ki MessageRetentionPeriod 604800 ke saath; queue-attributes.json se Standard email-queue aur invoice-queue banao (120 s visibility, 20 s polling, 3 receives).</p><p><b>2.</b> order-events Standard topic banao. Har matching queue-policy file set-queue-attributes se lagao; har file ek attributes string map hai jisme Policy hai.</p><p><b>3.</b> subscription.json se har queue ARN subscribe karo: raw=true, OrderPlaced ke liye MessageBody filter. file://order.json publish karo.</p><p><b>4.</b> Dono poore QueueUrls se max-number-of-messages 1 aur system attributes All ke saath receive karo. Har jawaab mein asli matching body aur nayi ReceiptHandle aani chahiye. Delete mat karo: is mission mein koi business consumer nahi chalta. Lab17 ack se pehle pakke intents dikhati hai.</p><p>Sirf SNS se aayi aaj ki deliveries ginti mein aati hain. Model wire checksums aur network scheduling nahi banata. Optional sleep N sirf messaging ka course clock turant aage badhata hai; asli shell sleep sach mein rukta hai.</p>',account:{region:R,now:'2026-10-26T00:00:00Z',queues:[],topics:[]},files:FILES,tasks:TASKS,solution:SOLUTION,hints:['Alag consumer copies ke liye alag queues chahiye. Publish se pehle retry target, scoped destination permission aur matching filter set karo.',SOLUTION.slice(0,4).join(' phir '),SOLUTION.slice(4,8).join(' phir '),SOLUTION.slice(8).join(' phir ')],success:AG.allOf(TASKS),successText:'SNS se aayi asli OrderPlaced body dono set ki gayi Standard queues se aaj ki receipts ke saath aayi; chhoti queue permission aur alag retry/DLQ contracts check hue. Bahar ki email/invoice poori hone ka daava nahi.'},
      {type:'docker',title:'🐳 Lab17: asli fan-out, pakke intents, DLQ',project:'17-sqs-sns-fanout-dlq',goal:'Scoped host/Moto API tests chalao aur AWS se asli farak dekho.',why:'Moto queue policy ke bina bhi deliver kar deta hai, aur delete ke baad FIFO dedup kho deta hai. State wala simulator likhe hue contracts test karta hai; emulator ka maan lena permission/runtime ka saboot nahi.',steps:[{text:'Pehle se bana env source karo aur lab script chalao; yeh apna naya loopback server banata hai aur sirf wahi band karta hai.',cmd:'source ../env.sh && ../.venv/bin/python -I lab.py',expect:'17 behaviour checks; cleanup milakar 18. Har consumer ko 2 copies milti hain par woh 1 pakka pending intent banata hai. Bahar ki emails 0.'},{text:'Output mein asli poison ke receive counts/body aur FIFO group ke observations dekho.',expect:'Source counts 1, 2, 3; takraane wala total 0 DLQ mein jaata hai, asli 499 wale intent ko overwrite kiye bina. A2 rukta hai jabki B1 aage badhta hai.'},{text:'README mein emulator ki kamiyan aur cleanup ledger padho.',expect:'Policy probe: receivesWithoutQueuePolicy [1,1]; dedupAfterDeleteBroken true. Aakhir mein queues/topics/tables [] aur OWNED MOTO STOPPED / LISTENER CLOSED.'}],observe:Q('Lab17 kya prove karti hai?', 'Duplicate input se har consumer ka ek matching pakka pending intent bana; bahar ke sends test nahi hue',['FIFO aur Moto ne milkar prove kiya ki har bahar ka payment/email crash ke baad bhi bilkul ek baar hota hai','Publish MessageId + khaali source queue ne prove kiya ki har invoice sahi process hua','Moto ne queue policies laagu ki, kyunki dono subscriptions ne confirmed ARNs lautaye'],2,'Asli DynamoDB conditional intents har consumer ke liye alag se duplicates jhel lete hain. Bahar ke sends nahi hue; khaali queues aur broker IDs business ka asar prove nahi karte; Moto ka policy laagu karna saaf alag nikla.')},
      {type:'quiz',title:'🎓 Delivery, order aur debugging ke faisle',questions:[
        Q('Teen email workers aur do invoice workers ek hi Standard queue share karte hain. Dono services ko har order chahiye. Repair?', 'SNS ke peeche har service ki ek queue banao; har service ke workers apni queue share karein',['Har ReceiveMessage batch 5 karo, taaki SQS har service ko hamesha ke liye same copies de de','Ek global FIFO MessageGroupId use karo, taaki har worker ko har order same total order mein mile','Visibility 14 din karo, taaki kisi worker ke delete karne se pehle dono services ko har message mil jaaye'],3,'Alag service copies ke liye fan-out aur alag queues chahiye. Batch size broadcast nahi karta; ek FIFO group kaam ko line mein laga deta hai; 14 din retention ki limit hai, visibility ki nahi, aur visibility broadcast nahi karti.'),
        Q('FIFO event se ek email gayi; worker DeleteMessage se pehle crash ho gaya. Ab kya zaroori hai?', 'Pakka dispatch contract + provider ki idempotency, ya pakka na pata result ke liye milaan',['Aur design nahi chahiye, kyunki FIFO ka 5 minute ka producer dedup saare email provider transactions bhi sambhal leta hai','Har send ke baad asli FIFO queue delete karna, taaki provider ko doosri delivery dikhe hi nahi','Har retry par MessageGroupId ko random value se badalna, taaki business event ki pehchaan bachi rahe'],0,'FIFO ka producer dedup bahar ki email ko atomic nahi banata. Ack se pehle crash kaam dohra sakta hai; queues delete karne se jobs kho jaate hain; random groups order khote hain aur business ki pehchaan nahi.'),
        Q('OrderPlaced ki body JSON hai; message attributes nahi hain. FilterPolicy type=OrderPlaced kuch deliver nahi karti. Kya check karein?', 'FilterPolicyScope ko MessageBody karo aur lagne ka time do; queue permission bhi check karo',['RawMessageDelivery ko false karo, kyunki raw delivery missing type attribute khud jod deti hai','Bada maxReceiveCount lagao, kyunki attribute wala filtering consumer processing ke baad hota hai','Source queue ki retention 60 second karo, taaki sirf-attribute wali policy message body padh le'],1,'Default scope attributes hai; body filtering saaf set karni padti hai. Raw/envelope format attribute nahi banata; receive ka retry budget aur retention filter scope ya permissions nahi badalte.'),
        Q('Processing aam taur par 45 s leti hai, visibility 30 s hai; worker ko jobs dohraaye dikhte hain. Sabse pehla sahi kadam?', 'Processing/ack ka lamba hissa naapo, visibility margin ke saath badhao ya extend karo, consumer idempotent rakho',['Visibility ki jagah 20 second ka long polling lagao, kyunki dono chal rahe jobs ko chhupaate hain','Receive hote hi har message delete karo, taaki processing fail hone par bhi dohraayi delivery na ho','Pehli koshish se pehle saare messages DLQ mein bhej do, taaki processing ke dauran queue na badhe'],2,'Visibility kaam/ack ke time se kam ho toh overlap hota hai. Lamba hissa naapo aur dhyaan se badhao; long polling kaam ka wait karta hai, jaldi delete fail kaam kho deta hai, aur pehle hi DLQ processing nahi hai.'),
        Q('Payload ka takraav 3 baar dohraya; source redrive maxReceiveCount 3; DLQ mein asli kharab body aayi. Ab kya?', 'Wajah dekho/theek karo, saboot bachao, canary redrive karo aur consumer ke business result check karo',['DLQ turant purge karo, kyunki alag kiya gaya har message apna business kaam pehle hi poora kar chuka hai','maxReceiveCount bina limit badhao, kyunki wahi galat orderId kaafi retries ke baad sahi ho jaata hai','Source aur DLQ dono delete karke wahi naam dobara banao, taaki gayab messages safal recovery gine jaayein'],3,'DLQ alag rakhna hai, kaam poora hona nahi. Theek karo, phir control ke saath replay/milaan; purge/delete se events kho jaate hain; pakki kharabi bina limit retries se theek nahi hoti.'),
        Q('Har account mein order chahiye, aur ek alag analytics bhi jise best-effort order chalega. Kya chunoge?', 'SNS FIFO se account processing ki SQS FIFO aur analytics ki SQS Standard, har queue ki scoped permission ke saath',['SNS FIFO seedha customer email aur HTTP endpoints par, kyunki saare push protocols FIFO order bachate hain','SNS Standard se ek global SQS FIFO queue, kyunki Standard topics har zaroori FIFO sequence dete hain','MessageGroupId wali ek Standard queue, kyunki fair queues har tenant ko sakht FIFO bana deti hain'],0,'Aaj SNS FIFO dono queue types support karta hai; Standard best-effort/at-least-once hi rehta hai. Customer ke push endpoints FIFO nahi; Standard topic FIFO queue wala delivery contract nahi de sakta; fair Standard groups FIFO nahi bante.'),
        Q('Lambda timeout 10 s, batch window 5 s. Validation aur recommended visibility mein farak kya hai?', 'Kam se kam 10 s timeout validation paas karta hai; is config ke liye AWS ki recommendation 65 s hai',['Visibility 5 s honi chahiye, kyunki batching window function ki deadline ki jagah le leti hai','Visibility 10 s hi AWS ki poori recommendation hai, aur throttling ke retry ki jagah nahi chahiye','Visibility 60 s exact recommendation hai, kyunki batching window formula mein nahi aati'],1,'Minimum function timeout hai; recommended 6 × timeout + window = 65 s. 5 s basic validation fail karta hai; 10 s mein recommended margin nahi; 60 s set ki gayi window chhod deta hai.'),
        Q('3 crore/mahina ke fan-out andaaze mein sirf Publish calls gini gayi. Request model mein aur kya jodna chahiye?', 'Har queue ke send/receive/delete aur payload units, polls/retries/batches aur baaki kharche ke meters ke saath',['Sirf queue ki storage GB, kyunki SNS publish ke baad SQS receive/delete calls ka meter nahi chalta','Sirf consumers ki ginti, kyunki ek worker process ek billable mahine ki queue request ke barabar hai','Aur kuch nahi, kyunki SNS → SQS ki har message delivery fees nahi, toh aage ka saara kaam free hai'],2,'SQS requests ka meter alag chalta hai; payload ke hisse, retries/polls/batches units badalte hain. SNS ki SQS delivery fees na hone se SQS, transfer, filtering, KMS ya workers ka kharcha nahi hatta; workers ki ginti requests ki ginti nahi.')
      ]}
    ],
    interview:{title:'Interview: delivery ka saboot aur poison ko alag karna',instructions:'Chaar faislon ke baad purani invoice source/DLQ bachate hue retry theek karo aur asli poison ko padh kar dikhao.',questions:[
      Q('Ek shared intent table mein sirf eventId ki jagah consumer#eventId wali dedup key zyada safe kyun hai?', 'Alag email aur invoice consumers ko ek hi business event ke alag pakke intents chahiye',['Shared eventId ko jaan-boojh kar invoice rok dena chahiye jab email pehle order process kar le','Consumer ka naam jodne se har dohraayi delivery unique ho jaati hai aur payload check ki zaroorat nahi rehti','Yeh key SNS ke kisi bhi queue tak publish karne se pehle saare transport duplicates rok deti hai'],3,'Ek business event ke kai alag asar chahiye ho sakte hain. Consumer ka scope ek service ko doosri ko rokne se bachata hai; same consumer/event dobara aaye toh check ke liye takraata hai; DB key transport ka publish nahi rokti.'),
      Q('Same consumer/eventId ka total 499 wala pending intent pehle se hai; duplicate ab total 0 bol raha hai. Ack karein?', 'Takraane wali pehchaan reject karo, asli intent bachao aur aankh band karke ack ki jagah dekho/alag rakho',['Asli total ko chupchaap overwrite karo, kyunki har dohraaya eventId ek naya sudhaar hi hota hai','Turant ack karo, kyunki pehle se bani conditional-write failure prove karti hai ki naya payload safe hai','Retries ke dauran random eventId banao, taaki takraane wala payload duplicate checks ko bypass kare'],0,'Pehle se bani row sirf pehchaan ka takraav prove karti hai; poora maksad wala operation compare karo. Alag payload ko saaf conflict handling chahiye; chupchaap overwrite, bina dekhe ack ya random IDs kharabi/duplicates chhupa dete hain.'),
      Q('SNS ke paas queue-policy permission na ho, toh source processing DLQ khaali kyun reh sakti hai?', 'Event source queue mein kabhi aaya hi nahi; SNS delivery failure aur subscription DLQ ka config dekho',['SQS processing DLQ mein sirf safal process hue messages hote hain, isliye woh policy errors nahi dekhti','Visibility timeout har na pahunche SNS publish ko seedha source processing DLQ mein bhej deta hai','Confirmed subscription queue policy ki guarantee hai, isliye khaali DLQ matlab har subscriber ne kaam poora kiya'],1,'Consumer retry DLQ un messages par chalti hai jo SQS mein aa chuke hain. Delivery failures SNS delivery diagnostics/subscription DLQ ki hain; confirmation permission ya business ka poora hona nahi.'),
      Q('Worker dedup flag likhta hai, phir email bhejne se pehle crash; retry pehle se bane flags chhod deta hai. Sahi design?', 'Wapas laaya ja sakne wala pending intent save karo, aur idempotent provider key ya milaan se dispatch karo',['FIFO dedup window 14 din karo, taaki chhooti hui bahar ki email apne aap pahunch jaaye','Chhoota source message jaldi delete karo, taaki provider queue depth se missing email ka andaaza laga le','MessageGroupId ko akela pakka flag maano, kyunki FIFO groups bahar ke dispatch ka poora hona yaad rakhte hain'],2,'Pending intent wapas laaya ja sake, aur bahar ka anjaana result sambhala jaaye. FIFO ka 5 minute ka dedup 14 din ka email recovery nahi ban sakta; message delete karne se dispatch nahi hota; group ka order provider ka result nahi rakhta.'),
      {terminal:{title:'🖥️ Retry contract theek karo; asli poison alag karo',goal:'<p>invoice-queue mein pehle original-poison (orderId=null) hai, phir original-good; orders-dlq pehle se bana hai. Dono queues ki pehchaan aur asli achha event bachao.</p><p>queue-attributes.json lagao: visibility 120 s, poll 20 s, redrive 3. Source ko max-number-of-messages 1 aur visibility-timeout 0 ke saath 3 baar receive karo, taaki wahi fail event jaan-boojh kar turant dobara aaye. Poison ko ack mat karo.</p><p>Phir default 120 s se source receive karo: poison DLQ mein jaane ke baad achha event aana chahiye. Aakhir mein orders-dlq receive karke asli poison body/count dekho. Achhe event ko ack mat karo: business ka kaam nahi chala. Zero timeout sirf local jaan-boojh kar fail karne ki exercise hai, production ki salah nahi.</p>',account:iSeed(),files:FILES,tasks:iTasks,solution:iSolution,hints:['Queue depth zero se jeet nahi milegi. Asli IDs bachao, retry budget ke baad asli poison bhejo, aur dono asli bodies padho.',iSolution[0],iSolution.slice(1,4).join(' phir '),iSolution.slice(4).join(' phir ')],success:AG.allOf(iTasks),successText:'Purani source/DLQ bachi. Asli poison 3 source attempts ke baad asli DLQ mein gaya aur aakhri receive ne body lautayi; achha event pakke business processing ke liye bacha hai. Na purge/delete hua, na bahar ki safalta ka daava.'}}
    ]},
    success:['Delivery ka accept hona aur business ka poora hona alag prove kar sakta hoon','Policy/filter/visibility/receipt/DLQ ki state dekh sakta hoon','FIFO group/dedup aur idempotent dispatch ki boundaries chun sakta hoon','Queue/fan-out/stream/broker ke contract aur request ka kharcha compare kar sakta hoon'],
    homework:'<p><b>Optional, sirf approved AWS sandbox mein (paisa lagega).</b> Region/quota/budget aur aaj ke daam check karo. Apna topic, har service ki queue, scoped resource/key/identity policies, processing DLQs aur alag subscription delivery DLQ banao. Filter lagne ke baad matching/non-matching body/attribute filters test karo, provider-idempotent dispatch, dheema/crash hua consumer, poison ka retry/redrive, aur 5 minute ke andar delete ke baad FIFO duplicate ka asli behaviour dekho. Message IDs, business IDs, receive counts, umar, pakke asar aur delivery errors likho; asli customer events nahi. Sirf apni subscriptions/topics/queues/DLQs, test outbox table, logs/alarms, roles aur KMS resources (review kiye deletion schedule ke saath) saaf karo. Moto ke behaviour ya accept hue publish ko asli AWS ki security/performance ka saboot mat maano.</p>',
    cards:[{front:'Receive versus delete?',back:'Receive visibility reserve karta hai aur receipt deta hai; tay kiye pakke processing contract ke baad latest valid receipt se delete karo. Visibility khatam hone par retry ho sakta hai.'},{front:'Saari services ke liye ek queue?',back:'Ek queue ke workers aapas mein bhidte hain. Alag email/invoice copies ke liye alag queues chahiye, aam taur par SNS ke peeche.'},{front:'SNS delivery permission?',back:'Producer ka Publish IAM + destination queue ki SendMessage resource policy, topic SourceArn tak scoped; zaroori KMS permissions bhi maayne rakhti hain.'},{front:'Filter reads body?',back:'Default scope MessageAttributes. JSON payload fields ke liye saaf MessageBody; raw/envelope consumer ke format ka alag chunav hai.'},{front:'FIFO se business ka kaam exactly once?',back:'Bahar ke kaam ki apne aap atomicity nahi. Har group ka order + 5 minute ka producer dedup; consumer crash ya ack ka result pata na ho, toh pakki pehchaan aur idempotent asar phir bhi chahiye.'},{front:'Two DLQ contracts?',back:'Delivery failures ke liye SNS subscription DLQ; queue mein aa chuke, retries khatam jobs ke liye SQS source processing DLQ. Redrive se pehle dekho.'},{front:'Conditional dedup flag kaafi hai?',back:'Kaam se pehle flag lagao toh kaam kho sakta hai; baad mein lagao toh dohra sakta hai. Wapas laaya ja sakne wala pakka intent + idempotent/milaan wala dispatch is boundary ko sambhalta hai.'},{front:'Queue planner kya prove karta hai?',back:'Bataye gaye retry/capacity/window ka hisaab. AWS ka throughput, latency, random duplicates ya exact DLQ timing ka naap nahi.'}]
  }]);
})();
